// Real-time Schwarzschild black hole, after Eric Bruneton's black_hole_shader
// (https://github.com/ebruneton/black_hole_shader, commit e72b3f2, BSD-3-Clause, Copyright (c) 2020 Eric Bruneton).
// Ported pieces, kept close to the originals:
//  - black_hole/functions.glsl: texture mappings, LookupRayDeflection/LookupRayInverseRadius, TraceRay (verbatim)
//  - black_hole/model.glsl: SceneColor (lensing, Doppler factors, disc compositing), DefaultDiscColor,
//    DefaultStarColor (footprint-filtered stars with lensing amplification), BlackBodyColor
//  - black_hole/preprocess/functions.cc: ComputeRayDeflectionTexture/ComputeRayInverseRadiusTexture
//    (C++ preprocessing, ported to JS and run here in setup, with dphi = 1e-4 instead of 1e-5)
//  - black_hole/demo/camera_view/shader_manager.js: generateDiscParticleParams (the disc's orbiting particles)
//  - black_hole/demo/camera_view/fragment_shader.glsl: TraceRayEuclidean (the "no lensing" toggle), Noise
//  - black_hole/demo/model/model.js: the static observer's reference frame (e_tau, e_w, e_h, e_d, k_s)
//  - color_maps/colors.cc + black_body_texture_generator.cc: Planck spectrum x CIE 1931 2° CMFs -> clamped
//    linear sRGB (the CMF table colors.inc and noise_texture.png are fetched from the repo at that commit)
//  - bloom/bloom.js: the tone map, pow(1 - exp(-c), 1/2.2)
// Not ported: the Gaia star cube maps (hundreds of MB of generated data) are replaced by a procedural star field
// and Milky Way band; the camera is a static observer (no free-fall orbits, so no Doppler on the background stars).
// The Copyright notice and BSD-3-Clause conditions of the original apply to the ported code.
const gl = ctx.gl;
if (!gl.getExtension("EXT_color_buffer_float")) throw new Error("This scene needs float render targets (EXT_color_buffer_float).");
const floatLinear = !!gl.getExtension("OES_texture_float_linear");
const REPO = "https://cdn.jsdelivr.net/gh/ebruneton/black_hole_shader@e72b3f293409893a6fa25528b29572c96fc57f57";

// ---- Precomputed textures (preprocess/functions.cc, ported) ----
const kMu = 4 / 27;
const DW = 512, DH = 512, IW = 64, IH = 32;
function vFromEsquareAndU(e2, u) {
  if (e2 > kMu) {
    const x = u < 2 / 3 ? -Math.sqrt(2 / 3 - u) : Math.sqrt(u - 2 / 3);
    return (Math.sqrt(2 / 3) + x) / (Math.sqrt(2 / 3) + Math.sqrt(1 / 3));
  }
  const x = (2 / kMu) * e2 - 1, ua = 1 / 3 + (2 / 3) * Math.sin(Math.asin(x) / 3);
  return 1 - Math.sqrt(Math.max(1 - u / ua, 0));
}
const DPHI = 1e-4;
// Ray deflection D(e, u) and time, integrating u'' = 3/2 u^2 - u along phi (semi-implicit Euler, as the original).
const deflection = new Float32Array(DW * DH * 4);
for (let i = 0; i < DW; i++) {
  const tu = i / (DW - 1), x = 1 - Math.exp(-50 * (tu - 0.5) * (tu - 0.5));
  const e2 = tu < 0.5 ? kMu * x : kMu / x, e = Math.sqrt(e2);
  let t = 0, u = 0, ud = e, phi = 0, pd = 0, pt = 0, pj = 0;
  for (;;) {
    if (u >= 1 || ud < 0) { const o = ((DH - 1) * DW + i) * 4; deflection[o] = pd; deflection[o + 1] = pt; break; }
    const d = phi - Math.atan2(u, ud), j = vFromEsquareAndU(e2, u) * (DH - 1);
    for (let k = Math.ceil(pj), k1 = Math.ceil(j); k < k1; k++) {
      const l = (k - pj) / (j - pj), o = (k * DW + i) * 4;
      deflection[o] = pd * (1 - l) + d * l; deflection[o + 1] = pt * (1 - l) + t * l;
    }
    pd = d; pt = t; pj = j;
    if (u > 1e-2) t += (e / (u * u * (1 - u))) * DPHI;
    ud += (1.5 * u * u - u) * DPHI; u += ud * DPHI; phi += DPHI;
  }
}
// Ray inverse radius U(e, phi) and time.
const inverseRadius = new Float32Array(IW * IH * 4);
for (let i = 0; i < IW; i++) {
  const tu = Math.min(Math.max(i / (IW - 1), 0.001), 0.999);
  const e2 = (1 / tu - 1) / 6, e = Math.sqrt(e2);
  const phiUb = (1 + e2) / (1 / 3 + 2 * e2 * Math.sqrt(e2));
  let t = 0, u = 0, ud = e, phi = 0, pu = 0, pt = 0, pj = 0;
  for (;;) {
    const j = (phi / phiUb) * (IH - 1), k1 = Math.min(Math.ceil(j), IH);
    for (let k = Math.ceil(pj); k < k1; k++) {
      const l = (k - pj) / (j - pj), o = (k * IW + i) * 4;
      inverseRadius[o] = pu * (1 - l) + u * l; inverseRadius[o + 1] = pt * (1 - l) + t * l;
    }
    if (k1 === IH) break;
    pu = u; pt = t; pj = j;
    if (u > 1e-2) t += (e / (u * u * (1 - u))) * DPHI;
    ud += (1.5 * u * u - u) * DPHI; u += ud * DPHI; phi += DPHI;
  }
}
const fmt = floatLinear
  ? { internalFormat: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT, filter: gl.LINEAR }
  : { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.FLOAT, filter: gl.LINEAR };
const deflectionTex = ctx.utils.uploadDataTexture(gl, null, DW, DH, deflection, fmt);
const inverseRadiusTex = ctx.utils.uploadDataTexture(gl, null, IW, IH, inverseRadius, fmt);

// ---- Black body colors (color_maps/colors.cc, ported): T = 100 exp(6 (i + 0.5) / N) ----
let cmf = null; // rows of [lambda, x, y, z], 360..830 nm every 5 nm
try {
  const src = await (await fetch(`${REPO}/color_maps/colors.inc`)).text();
  const nums = src.slice(src.indexOf("CIE_2_DEG_COLOR_MATCHING_FUNCTIONS")).split("{")[1].split("}")[0].split(",").map(Number).filter((v) => !Number.isNaN(v));
  if (nums.length >= 380) cmf = nums;
} catch { /* fall back to Wyman et al.'s analytic fit below */ }
const g = (x, m, s1, s2) => { const t = (x - m) / (x < m ? s1 : s2); return Math.exp(-0.5 * t * t); };
function cmfAt(lambda, c) {
  if (cmf) {
    if (lambda <= 360 || lambda >= 830) return 0;
    const f = (lambda - 360) / 5, row = Math.floor(f), w = f - row;
    return cmf[4 * row + c] * (1 - w) + cmf[4 * (row + 1) + c] * w;
  }
  if (c === 1) return 1.056 * g(lambda, 599.8, 37.9, 31) + 0.362 * g(lambda, 442, 16, 26.7) - 0.065 * g(lambda, 501.1, 20.4, 26.2);
  if (c === 2) return 0.821 * g(lambda, 568.8, 46.9, 40.5) + 0.286 * g(lambda, 530.9, 16.3, 31.1);
  return 1.217 * g(lambda, 437, 11.8, 36) + 0.681 * g(lambda, 459, 26, 13.8);
}
function xyzFromTemperature(T) {
  const c = 299792458, h = 6.62607015e-34, kB = 1.380649e-23;
  const xyz = [0, 0, 0];
  for (let lambda = 360; lambda < 830; lambda++) {
    const l = lambda * 1e-9, L = (2 * h * c * c) / (Math.pow(l, 5) * (Math.exp((h * c) / (l * kB * T)) - 1));
    for (let k = 0; k < 3; k++) xyz[k] += cmfAt(lambda, k + 1) * L * 1e-9;
  }
  return xyz;
}
const toSrgb = (X, Y, Z) => [3.2406 * X - 1.5372 * Y - 0.4986 * Z, -0.9689 * X + 1.8758 * Y + 0.0415 * Z, 0.0557 * X - 0.204 * Y + 1.057 * Z];
const toXyz = (r, gg, b) => [0.4124 * r + 0.3576 * gg + 0.1805 * b, 0.2126 * r + 0.7152 * gg + 0.0722 * b, 0.0193 * r + 0.1192 * gg + 0.9505 * b];
const xyOf = (rgb) => { const p = toXyz(...rgb), s = p[0] + p[1] + p[2]; return [p[0] / s, p[1] / s]; };
const [pR, pG, pB, pW] = [xyOf([1, 0, 0]), xyOf([0, 1, 0]), xyOf([0, 0, 1]), xyOf([1, 1, 1])];
function maybeClamp(A, B, xy) {
  const dx = xy[0] - pW[0], dy = xy[1] - pW[1], ex = B[0] - A[0], ey = B[1] - A[1], fx = A[0] - pW[0], fy = A[1] - pW[1];
  const det = dx * ey - dy * ex, t = (fx * ey - fy * ex) / det, s = (fx * dy - fy * dx) / det;
  if (t > 0 && t < 1 && s >= 0 && s <= 1) { xy[0] = pW[0] + t * dx; xy[1] = pW[1] + t * dy; }
}
function clampedSrgb([X, Y, Z]) {
  const xy = [X / (X + Y + Z), Y / (X + Y + Z)];
  maybeClamp(pR, pG, xy); maybeClamp(pG, pB, xy); maybeClamp(pB, pR, xy);
  return toSrgb((xy[0] / xy[1]) * Y, Y, ((1 - xy[0] - xy[1]) / xy[1]) * Y);
}
const BB_N = 128, bb = new Float32Array(BB_N * 4), bbY = new Float64Array(BB_N);
// Normalized by the luminance of a 6500 K black body so half floats can hold it.
const yRef = xyzFromTemperature(6500)[1];
for (let i = 0; i < BB_N; i++) {
  const xyz = xyzFromTemperature(100 * Math.exp((6 * (i + 0.5)) / BB_N));
  const rgb = clampedSrgb(xyz);
  for (let k = 0; k < 3; k++) bb[i * 4 + k] = Math.max(rgb[k], 0) / yRef;
  bb[i * 4 + 3] = 1; bbY[i] = xyz[1] / yRef;
}
const blackBodyTex = ctx.utils.uploadDataTexture(gl, null, BB_N, 1, bb, fmt);
gl.bindTexture(gl.TEXTURE_2D, blackBodyTex);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
const luminanceAt = (T) => {
  const f = Math.min(Math.max((Math.log(T / 100) / 6) * BB_N - 0.5, 0), BB_N - 1), i = Math.floor(f), w = f - i;
  return bbY[i] * (1 - w) + bbY[Math.min(i + 1, BB_N - 1)] * w;
};

// ---- Disc noise (color_maps/noise_texture.png), with a procedural fallback ----
let noiseTex;
try {
  noiseTex = (await ctx.utils.loadTexture(`${REPO}/color_maps/noise_texture.png`, { wrap: "repeat", filter: "linear", mipmap: true })).texture;
} catch {
  const n = 128, data = new Uint8Array(n * n * 4);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 255;
  noiseTex = ctx.utils.uploadDataTexture(gl, null, n, n, data, { internalFormat: gl.RGBA8, format: gl.RGBA, type: gl.UNSIGNED_BYTE, filter: gl.LINEAR });
  gl.bindTexture(gl.TEXTURE_2D, noiseTex);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
}

// ---- Disc particles (shader_manager.js generateDiscParticleParams, verbatim logic) ----
function generateDiscParticleParams() {
  const rMin = 3.0, rMax = 12.0;
  const computeDthetaDphi = (u1, u2, u3) => {
    const k2 = (u2 - u1) / (u3 - u1), N = 100000;
    let K = 0.0;
    for (let i = 0; i < N; ++i) { const dy = 1.0 / N, y = (i + 0.5) / N; K += dy / Math.sqrt((1 - y * y) * (1 - k2 * y * y)); }
    return (Math.PI * Math.sqrt(u3 - u1)) / (4 * K);
  };
  const rings = [];
  for (let r1 = rMin; r1 < rMax; r1 += 0.75) {
    const e = 0.1 * Math.random(), r2 = (r1 * (1.0 + e)) / (1.0 - e);
    const u1 = 1 / r2, u2 = 1 / r1, u3 = 1 - u1 - u2, phi0 = 2 * Math.PI * Math.random();
    rings.push(`vec4(${u1.toPrecision(3)}, ${u2.toPrecision(3)}, ${phi0.toPrecision(3)}, ${computeDthetaDphi(u1, u2, u3).toPrecision(3)})`);
  }
  return `const float INNER_DISC_R = ${rMin.toPrecision(3)};
const float OUTER_DISC_R = ${rMax.toPrecision(3)};
const int NUM_DISC_PARTICLES = ${rings.length};
const vec4 DISC_PARTICLE_PARAMS[${rings.length}] = vec4[${rings.length}](
  ${rings.join(",\n  ")});`;
}

const HEADER = `#version 300 es
precision highp float;
precision highp sampler2D;
#define IN(x) const in x
#define OUT(x) out x
const float pi = ${Math.PI};
const float rad = 1.0;
const int RAY_DEFLECTION_TEXTURE_WIDTH = ${DW};
const int RAY_DEFLECTION_TEXTURE_HEIGHT = ${DH};
const int RAY_INVERSE_RADIUS_TEXTURE_WIDTH = ${IW};
const int RAY_INVERSE_RADIUS_TEXTURE_HEIGHT = ${IH};
const float STARS_CUBE_MAP_SIZE = 2048.0;
const float MAX_FOOTPRINT_SIZE = 4.0;
const float MAX_FOOTPRINT_LOD = 6.0;
#define Angle float
#define Real float
#define TimedAngle vec2
#define TimedInverseDistance vec2
#define RayDeflectionTexture sampler2D
#define RayInverseRadiusTexture sampler2D
`;

// black_hole/functions.glsl (Copyright (c) 2020 Eric Bruneton, BSD-3-Clause), code verbatim, doc comments removed.
const FUNCTIONS = `
const Real kMu = 4.0 / 27.0;
Real GetRayDeflectionTextureUFromEsquare(const Real e_square) {
  if (e_square < kMu) {
    return 0.5 - sqrt(-log(1.0 - e_square / kMu) * (1.0 / 50.0));
  } else {
    return 0.5 + sqrt(-log(1.0 - kMu / e_square) * (1.0 / 50.0));
  }
}
Real GetUapsisFromEsquare(const Real e_square) {
  Real x = (2.0 / kMu) * e_square - 1.0;
  return 1.0 / 3.0 + (2.0 / 3.0) * sin(asin(x) * (1.0 / 3.0));
}
Real GetRayDeflectionTextureVFromEsquareAndU(const Real e_square, const Real u) {
  if (e_square > kMu) {
    Real x = u < 2.0 / 3.0 ? -sqrt(2.0 / 3.0 - u) : sqrt(u - 2.0 / 3.0);
    return (sqrt(2.0 / 3.0) + x) / (sqrt(2.0 / 3.0) + sqrt(1.0 / 3.0));
  } else {
    return 1.0 - sqrt(max(1.0 - u / GetUapsisFromEsquare(e_square), 0.0));
  }
}
Real GetTextureCoordFromUnitRange(const Real x, const int texture_size) {
  return 0.5 / Real(texture_size) + x * (1.0 - 1.0 / Real(texture_size));
}
TimedAngle LookupRayDeflection(IN(RayDeflectionTexture) ray_deflection_texture,
                               const Real e_square, const Real u,
                               OUT(TimedAngle) deflection_apsis) {
  Real tex_u = GetTextureCoordFromUnitRange(GetRayDeflectionTextureUFromEsquare(e_square), RAY_DEFLECTION_TEXTURE_WIDTH);
  Real tex_v = GetTextureCoordFromUnitRange(GetRayDeflectionTextureVFromEsquareAndU(e_square, u), RAY_DEFLECTION_TEXTURE_HEIGHT);
  Real tex_v_apsis = GetTextureCoordFromUnitRange(1.0, RAY_DEFLECTION_TEXTURE_HEIGHT);
  deflection_apsis = TimedAngle(texture(ray_deflection_texture, vec2(tex_u, tex_v_apsis)));
  return TimedAngle(texture(ray_deflection_texture, vec2(tex_u, tex_v)));
}
Angle GetPhiUbFromEsquare(const Real e_square) {
  return (1.0 + e_square) / (1.0 / 3.0 + 2.0 * e_square * sqrt(e_square)) * rad;
}
Real GetRayInverseRadiusTextureUFromEsquare(const Real e_square) {
  return 1.0 / (1.0 + 6.0 * e_square);
}
TimedInverseDistance LookupRayInverseRadius(IN(RayInverseRadiusTexture) ray_inverse_radius_texture,
                                            const Real e_square, const Angle phi) {
  Real tex_u = GetTextureCoordFromUnitRange(GetRayInverseRadiusTextureUFromEsquare(e_square), RAY_INVERSE_RADIUS_TEXTURE_WIDTH);
  Real tex_v = GetTextureCoordFromUnitRange(phi / GetPhiUbFromEsquare(e_square), RAY_INVERSE_RADIUS_TEXTURE_HEIGHT);
  return TimedInverseDistance(texture(ray_inverse_radius_texture, vec2(tex_u, tex_v)));
}
Real FilteredPulse(Real edge0, Real edge1, Real x, Real fw) {
  fw = max(fw, 1e-6);
  Real x0 = x - fw * 0.5;
  Real x1 = x0 + fw;
  return max(0.0, (min(x1, edge1) - max(x0, edge0)) / fw);
}
Angle TraceRay(IN(RayDeflectionTexture) ray_deflection_texture,
               IN(RayInverseRadiusTexture) ray_inverse_radius_texture,
               const Real u, const Real u_dot, const Real e_square,
               const Angle delta, const Angle alpha, const Real u_ic,
               const Real u_oc, OUT(Real) u0, OUT(Angle) phi0, OUT(Real) t0,
               OUT(Real) alpha0, OUT(Real) u1, OUT(Angle) phi1, OUT(Real) t1,
               OUT(Real) alpha1) {
  u0 = -1.0;
  u1 = -1.0;
  if (e_square < kMu && u > 2.0 / 3.0) {
    return -1.0 * rad;
  }
  TimedAngle deflection_apsis;
  TimedAngle deflection = LookupRayDeflection(ray_deflection_texture, e_square, u, deflection_apsis);
  Angle ray_deflection = deflection.x;
  if (u_dot > 0.0) {
    ray_deflection = e_square < kMu ? 2.0 * deflection_apsis.x - ray_deflection : -1.0 * rad;
  }
  Real s = sign(u_dot);
  Angle phi = deflection.x + (s == 1.0 ? pi - delta : delta) + s * alpha;
  Angle phi_apsis = deflection_apsis.x + pi / 2.0;
  phi0 = mod(phi, pi);
  TimedInverseDistance ui0 = LookupRayInverseRadius(ray_inverse_radius_texture, e_square, phi0);
  if (phi0 < phi_apsis) {
    Real side = s * (ui0.x - u);
    if (side > 1e-3 || (side > -1e-3 && alpha < delta)) {
      u0 = ui0.x;
      phi0 = alpha + phi - phi0;
      t0 = s * (ui0.y - deflection.y);
    }
  }
  phi = 2.0 * phi_apsis - phi;
  phi1 = mod(phi, pi);
  TimedInverseDistance ui1 = LookupRayInverseRadius(ray_inverse_radius_texture, e_square, phi1);
  if (e_square < kMu && s == 1.0 && phi1 < phi_apsis) {
    u1 = ui1.x;
    phi1 = alpha + phi - phi1;
    t1 = 2.0 * deflection_apsis.y - ui1.y - deflection.y;
  }
  Real fw0 = min(fwidth(ui0.x), fwidth(u0 == -1.0 ? u1 : u0));
  Real fw1 = min(fwidth(ui1.x), fwidth(u1 == -1.0 ? u0 : u1));
  alpha0 = FilteredPulse(u_oc, u_ic, u0, fw0);
  alpha1 = FilteredPulse(u_oc, u_ic, u1, fw1);
  if (s == 1.0 && abs(e_square - kMu) < min(fwidth(e_square), kMu)) {
    if (alpha0 < 0.99) u0 = 2.0 / (1.0 / u_ic + 1.0 / u_oc);
    if (alpha1 < 0.99) u1 = 2.0 / (1.0 / u_ic + 1.0 / u_oc);
  }
  return ray_deflection;
}
`;

// The scene's own pieces (fragment_shader.glsl's role): procedural sky in place of the Gaia cube maps,
// TraceRayEuclidean for the "Lensing" toggle, and the disc shading hooks.
const SCENE = `
uniform vec4 camera_position;
uniform vec3 p;
uniform vec4 k_s;
uniform vec3 e_tau, e_w, e_h, e_d;
uniform sampler2D ray_deflection_texture, ray_inverse_radius_texture, black_body_texture, noise_texture;
uniform vec3 disc_params;      // density, opacity, temperature (as in the demo)
uniform float u_discScale;     // keeps the disc's brightness steady when its temperature changes
uniform float u_lensing, u_doppler, u_stars;
uniform mat3 stars_orientation;
uniform vec3 u_camera;         // half width, half height, focal length (pixels)
out vec4 outColor;

uint hash3(uvec3 v) {
  v = v * 1664525u + 1013904223u;
  v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
  v ^= v >> 16u;
  v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
  return v.x ^ v.y ^ v.z;
}
float rnd(inout uint s) { s = s * 747796405u + 2891336453u; uint w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u; return float((w >> 22u) ^ w) / 4294967295.0; }

// Value noise for the Milky Way band.
float vnoise(vec3 x) {
  vec3 i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f);
  float n = 0.0;
  for (int k = 0; k < 8; k++) {
    vec3 o = vec3(k & 1, (k >> 1) & 1, (k >> 2) & 1);
    float h = float(hash3(uvec3(ivec3(i + o) + 4096)) & 0xffffu) / 65535.0;
    vec3 w = mix(1.0 - f, f, o);
    n += h * w.x * w.y * w.z;
  }
  return n;
}
float fbm(vec3 x) { float s = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { s += a * vnoise(x); x = x * 2.03 + 17.1; a *= 0.5; } return s; }

vec3 GalaxyColor(vec3 dir) {
  dir = stars_orientation * dir;
  float lat = dir.y;
  float band = exp(-lat * lat / 0.018);
  float bulge = exp(-dot(dir.xz - vec2(1.0, 0.0), dir.xz - vec2(1.0, 0.0)) / 0.35) * exp(-lat * lat / 0.04);
  float clouds = fbm(dir * 5.0);
  float dust = smoothstep(0.42, 0.62, fbm(dir * 9.0 + 3.0)) * exp(-lat * lat / 0.004);
  float glow = (band * (0.35 + clouds) + 1.6 * bulge) * (1.0 - 0.85 * dust);
  vec3 tint = mix(vec3(0.55, 0.6, 1.0), vec3(1.0, 0.82, 0.62), clamp(bulge * 2.0 + clouds * 0.4, 0.0, 1.0));
  return u_stars * 0.028 * glow * tint + vec3(0.0004, 0.0005, 0.0008);
}

// One star per texel of a virtual cube map level 'lod' (the original reads Gaia/Tycho star cube maps here).
// Coarser levels hold one brighter star standing for the 4^lod texels they cover.
vec3 ProcStar(int face, ivec2 ij, float lod, out vec2 sub_position) {
  uint s = hash3(uvec3(uint(ij.x + 70000), uint(ij.y + 70000), uint(face) * 16u + uint(lod)));
  sub_position = vec2(rnd(s), rnd(s)) - 0.5;
  float presence = rnd(s), mag = rnd(s), tint = rnd(s);
  float flux = lod == 0.0 ? (presence < 0.012 ? pow(mag, 60.0) * 2.5 : 0.0) : exp2(2.0 * lod) * 1.2e-4 * (0.4 + 1.2 * mag);
  float T = 2600.0 * pow(18.0, tint * tint);
  vec3 c = texture(black_body_texture, vec2(log(T / 100.0) / 6.0, 0.5)).rgb;
  return u_stars * flux * c / max(dot(c, vec3(0.2126, 0.7152, 0.0722)), 1e-4);
}

// model.glsl DefaultStarColor (verbatim structure), with the cube map fetches replaced by ProcStar.
vec3 DefaultStarColor(vec3 dir, float lensing_amplification_factor, float min_lod) {
  vec3 dx_dir = dFdx(dir);
  vec3 dy_dir = dFdy(dir);
  vec3 abs_dir = abs(dir);
  float max_abs_dir_comp = max(abs_dir.x, max(abs_dir.y, abs_dir.z));
  int face = dir.z > 0.0 ? 0 : 1;
  if (max_abs_dir_comp == abs_dir.x) {
    face = dir.x > 0.0 ? 2 : 3;
    dir = dir.zyx; dx_dir = dx_dir.zyx; dy_dir = dy_dir.zyx;
  } else if (max_abs_dir_comp == abs_dir.y) {
    face = dir.y > 0.0 ? 4 : 5;
    dir = dir.xzy; dx_dir = dx_dir.xzy; dy_dir = dy_dir.xzy;
  }
  float inv_dir_z = 1.0 / dir.z;
  vec2 uv = dir.xy * inv_dir_z;
  vec2 dx_uv = (dx_dir.xy - uv * dx_dir.z) * inv_dir_z;
  vec2 dy_uv = (dy_dir.xy - uv * dy_dir.z) * inv_dir_z;
  vec2 d_uv = max(abs(dx_uv + dy_uv), abs(dx_uv - dy_uv));
  vec2 fwidth_uv = (0.5 * STARS_CUBE_MAP_SIZE / MAX_FOOTPRINT_SIZE) * d_uv;
  float lod = max(ceil(max(log2(fwidth_uv.x), log2(fwidth_uv.y))), min_lod);
  float lod_width = (0.5 * STARS_CUBE_MAP_SIZE) / pow(2.0, lod);
  if (lod > MAX_FOOTPRINT_LOD || abs(determinant(mat2(dx_uv, dy_uv))) < 1e-14) {
    return u_stars * vec3(6.0e-5);   // average star light (StarTextureColor(dir) in the original)
  }
  mat2 to_screen_pixel_coords = inverse(mat2(dx_uv, dy_uv));
  ivec2 ij0 = ivec2(floor((uv - d_uv) * lod_width));
  ivec2 ij1 = ivec2(floor((uv + d_uv) * lod_width));
  vec3 color_sum = vec3(0.0);
  for (int j = ij0.y; j <= ij1.y; ++j) {
    for (int i = ij0.x; i <= ij1.x; ++i) {
      vec2 texel_uv = (vec2(i, j) + vec2(0.5)) / lod_width;
      vec2 delta_uv;
      vec3 star_color = ProcStar(face, ivec2(i, j), lod, delta_uv);
      vec2 star_uv = uv - texel_uv + delta_uv / lod_width;
      vec2 star_pixel_coords = to_screen_pixel_coords * star_uv;
      vec2 overlap = max(vec2(1.0) - abs(star_pixel_coords), 0.0);
      color_sum += star_color * overlap.x * overlap.y;
    }
  }
  return color_sum * lensing_amplification_factor;
}

vec3 StarColor(vec3 dir, float lensing_amplification_factor) {
  dir = stars_orientation * dir;
  return DefaultStarColor(dir, lensing_amplification_factor, 0.0);
}

vec3 Doppler(vec3 rgb, float doppler_factor) { return rgb; }  // static observer: shift of 1/sqrt(1-u), negligible

float Noise(vec2 uv) { return 3.0 * (texture(noise_texture, uv).r - 0.5) + 1.0; }

vec3 BlackBodyColor(sampler2D black_body_texture, float temperature) {
  float tex_u = (1.0 / 6.0) * log(temperature * (1.0 / 100.0));
  return texture(black_body_texture, vec2(tex_u, 0.5)).rgb;
}

// model.glsl DefaultDiscColor (verbatim).
vec4 DefaultDiscColor(vec2 p, float p_t, bool top_side, float doppler_factor,
                      float disc_temperature, sampler2D black_body_texture) {
  float p_r = length(p);
  float p_phi = atan(p.y, p.x);
  float density = 0.0;
  for (int i = 0; i < NUM_DISC_PARTICLES; ++i) {
    vec4 params = DISC_PARTICLE_PARAMS[i];
    float u1 = params.x;
    float u2 = params.y;
    float phi0 = params.z;
    float dtheta_dphi = params.w;
    float u_avg = (u1 + u2) * 0.5;
    float dphi_dt = u_avg * sqrt(0.5 * u_avg);
    float phi = dphi_dt * p_t + phi0;
    float a = mod(p_phi - phi, 2.0 * pi);
    float s = sin(dtheta_dphi * (a + phi));
    float r = 1.0 / (u1 + (u2 - u1) * s * s);
    vec2 d = vec2(a - pi, r - p_r) * vec2(1.0 / pi, 0.5);
    float noise = Noise(d * vec2(p_r / OUTER_DISC_R, 1.0));
    density += smoothstep(1.0, 0.0, length(d)) * noise;
  }
  const float r_max = 49.0 / 12.0;
  const float temperature_profile_max = pow((1.0 - sqrt(3.0 / r_max)) / (r_max * r_max * r_max), 0.25);
  float temperature_profile = pow((1.0 - sqrt(3.0 / p_r)) / (p_r * p_r * p_r), 0.25);
  float temperature = disc_temperature * temperature_profile * (1.0 / temperature_profile_max);
  vec3 color = max(density, 0.0) * BlackBodyColor(black_body_texture, temperature * doppler_factor);
  float alpha = smoothstep(INNER_DISC_R, INNER_DISC_R * 1.2, p_r) * smoothstep(OUTER_DISC_R, OUTER_DISC_R / 1.2, p_r);
  return vec4(color * alpha, alpha);
}

vec4 DiscColor(vec2 p, float t, bool top_side, float doppler_factor) {
  if (u_doppler < 0.5) doppler_factor = 1.0;
  vec4 color = DefaultDiscColor(p, t, top_side, doppler_factor, disc_params.z, black_body_texture);
  return vec4(disc_params.x * u_discScale * color.rgb, disc_params.y * color.a);
}

// fragment_shader.glsl TraceRayEuclidean (verbatim): flat space-time, for the "Lensing" toggle.
float TraceRayEuclidean(float p_r, float delta, float alpha, float u_ic,
                        float u_oc, out float u0, out float phi0, out float t0,
                        out float u1, out float phi1, out float t1) {
  float cos_delta = cos(delta);
  float sin_delta = sin(delta);
  float tan_alpha = tan(alpha);
  float det = 1.0 - p_r * p_r * sin_delta * sin_delta;
  float deflection = det > 0.0 && cos_delta < 0.0 ? -1.0 : 0.0;
  u0 = -1.0;
  u1 = -1.0;
  float t = p_r / (sin_delta / tan_alpha - cos_delta);
  float r = length(vec2(p_r + t * cos_delta, t * sin_delta));
  if (t >= 0.0 && r * u_oc <= 1.0 && r * u_ic >= 1.0 && (deflection == 0.0 || t < p_r)) {
    u0 = 1.0 / r;
    phi0 = alpha;
    t0 = t;
  }
  return deflection;
}

float RayTrace(float u, float u_dot, float e_square, float delta, float alpha,
               float u_ic, float u_oc, out float u0, out float phi0,
               out float t0, out float alpha0, out float u1, out float phi1,
               out float t1, out float alpha1) {
  if (u_lensing > 0.5) {
    return TraceRay(ray_deflection_texture, ray_inverse_radius_texture, u, u_dot, e_square, delta, alpha, u_ic, u_oc,
                    u0, phi0, t0, alpha0, u1, phi1, t1, alpha1);
  }
  alpha0 = 1.0;
  alpha1 = 1.0;
  return TraceRayEuclidean(1.0 / u, delta, alpha, u_ic, u_oc, u0, phi0, t0, u1, phi1, t1);
}
`;

// model.glsl SceneColor (verbatim).
const SCENE_COLOR = `
vec3 SceneColor(vec4 camera_position, vec3 p, vec4 k_s, vec3 e_tau, vec3 e_w,
                vec3 e_h, vec3 e_d, vec3 view_dir) {
  vec3 q = normalize(view_dir);
  vec3 d = -e_tau + q.x * e_w + q.y * e_h + q.z * e_d;
  vec3 e_x_prime = normalize(p);
  vec3 e_z_prime = normalize(cross(e_x_prime, d));
  vec3 e_y_prime = normalize(cross(e_z_prime, e_x_prime));
  const vec3 e_z = vec3(0.0, 0.0, 1.0);
  vec3 t = normalize(cross(e_z, e_z_prime));
  if (dot(t, e_y_prime) < 0.0) {
    t = -t;
  }
  float alpha = acos(clamp(dot(e_x_prime, t), -1.0, 1.0));
  float delta = acos(clamp(dot(e_x_prime, normalize(d)), -1.0, 1.0));
  float u = 1.0 / camera_position[1];
  float u_dot = -u / tan(delta);
  float e_square = u_dot * u_dot + u * u * (1.0 - u);
  float e = -sqrt(e_square);
  const float U_IC = 1.0 / INNER_DISC_R;
  const float U_OC = 1.0 / OUTER_DISC_R;
  float u0, phi0, t0, alpha0, u1, phi1, t1, alpha1;
  float deflection = RayTrace(u, u_dot, e_square, delta, alpha, U_IC, U_OC,
                              u0, phi0, t0, alpha0, u1, phi1, t1, alpha1);
  vec4 l = vec4(e / (1.0 - u), -u_dot, 0.0, u * u);
  float g_k_l_receiver = k_s.x * l.x * (1.0 - u) - k_s.y * l.y / (1.0 - u) -
                         u * dot(e_tau, e_y_prime) * l.w / (u * u);
  float delta_prime = delta + max(deflection, 0.0);
  vec3 d_prime = cos(delta_prime) * e_x_prime + sin(delta_prime) * e_y_prime;
  vec3 color = vec3(0.0, 0.0, 0.0);
  if (deflection >= 0.0) {
    float g_k_l_source = e;
    float doppler_factor = g_k_l_receiver / g_k_l_source;
    float omega = length(cross(dFdx(q), dFdy(q)));
    float omega_prime = length(cross(dFdx(d_prime), dFdy(d_prime)));
    float lensing_amplification_factor = omega / omega_prime;
    lensing_amplification_factor = min(lensing_amplification_factor, 1e6);
    float pixel_area = max(omega * (1024.0 * 1024.0), 1.0);
    color += GalaxyColor(d_prime);
    color += StarColor(d_prime, lensing_amplification_factor / pixel_area);
    color = Doppler(color, doppler_factor);
  }
  if (u1 >= 0.0 && alpha1 > 0.0) {
    float g_k_l_source = e * sqrt(2.0 / (2.0 - 3.0 * u1)) -
                         u1 * sqrt(u1 / (2.0 - 3.0 * u1)) * dot(e_z, e_z_prime);
    float doppler_factor = g_k_l_receiver / g_k_l_source;
    bool top_side = (mod(abs(phi1 - alpha), 2.0 * pi) < 1e-3) == (e_x_prime.z > 0.0);
    vec3 i1 = (e_x_prime * cos(phi1) + e_y_prime * sin(phi1)) / u1;
    vec4 disc_color = DiscColor(i1.xy, camera_position[0] - t1, top_side, doppler_factor);
    color = color * (1.0 - disc_color.a) + alpha1 * disc_color.rgb;
  }
  if (u0 >= 0.0 && alpha0 > 0.0) {
    float g_k_l_source = e * sqrt(2.0 / (2.0 - 3.0 * u0)) -
                         u0 * sqrt(u0 / (2.0 - 3.0 * u0)) * dot(e_z, e_z_prime);
    float doppler_factor = g_k_l_receiver / g_k_l_source;
    bool top_side = (mod(abs(phi0 - alpha), 2.0 * pi) < 1e-3) == (e_x_prime.z > 0.0);
    vec3 i0 = (e_x_prime * cos(phi0) + e_y_prime * sin(phi0)) / u0;
    vec4 disc_color = DiscColor(i0.xy, camera_position[0] - t0, top_side, doppler_factor);
    color = color * (1.0 - disc_color.a) + alpha0 * disc_color.rgb;
  }
  return color;
}

void main() {
  // camera_view/vertex_shader.glsl: view_dir = (vertex.xy * camera_size.xy, -focal length)
  vec3 view_dir = vec3(gl_FragCoord.xy - u_camera.xy, -u_camera.z);
  outColor = vec4(min(SceneColor(camera_position, p, k_s, e_tau, e_w, e_h, e_d, view_dir), vec3(6.0e4)), 1.0);
}
`;

const sceneProgram = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, HEADER + generateDiscParticleParams() + FUNCTIONS + SCENE + SCENE_COLOR);

// Bloom: a mip pyramid of the HDR image, blurred back up, mixed in and tone mapped like bloom/bloom.js.
const PH = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;
uniform sampler2D u_src;
uniform vec2 u_texel;
`;
const downProgram = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, PH + `
void main() {
  vec2 o = u_texel;
  vec3 c = texture(u_src, v_uv).rgb * 4.0
    + texture(u_src, v_uv + vec2(-o.x, -o.y)).rgb + texture(u_src, v_uv + vec2(o.x, -o.y)).rgb
    + texture(u_src, v_uv + vec2(-o.x, o.y)).rgb + texture(u_src, v_uv + vec2(o.x, o.y)).rgb;
  outColor = vec4(min(c / 8.0, vec3(6.0e4)), 1.0);
}`);
const upProgram = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, PH + `
uniform sampler2D u_add;
void main() {
  vec2 o = u_texel;
  vec3 c = texture(u_src, v_uv).rgb * 4.0
    + (texture(u_src, v_uv + vec2(-o.x, 0.0)).rgb + texture(u_src, v_uv + vec2(o.x, 0.0)).rgb
     + texture(u_src, v_uv + vec2(0.0, -o.y)).rgb + texture(u_src, v_uv + vec2(0.0, o.y)).rgb) * 2.0
    + texture(u_src, v_uv - o).rgb + texture(u_src, v_uv + o).rgb
    + texture(u_src, v_uv + vec2(o.x, -o.y)).rgb + texture(u_src, v_uv + vec2(-o.x, o.y)).rgb;
  outColor = vec4(c / 16.0 + texture(u_add, v_uv).rgb, 1.0);
}`);
const finalProgram = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, PH + `
uniform sampler2D u_bloom;
uniform float u_bloomMix, u_exp, u_levels;
void main() {
  vec3 src = texture(u_src, v_uv).rgb;
  vec3 bloom = texture(u_bloom, v_uv).rgb / u_levels;
  vec3 color = mix(src, bloom, u_bloomMix) * u_exp;
  color = min(color, 10.0);
  color = pow(vec3(1.0) - exp(-color), vec3(1.0 / 2.2));
  outColor = vec4(color, 1.0);
}`);

// Orbit camera (drag orbits, scroll zooms); its eye is mapped to Schwarzschild coordinates in render.
const camera = ctx.utils.createOrbitCamera({ distance: ctx.uniforms.u_distance ?? 26, theta: 0.6, phi: 1.47, minDistance: 3.2, maxDistance: 90 });

Object.assign(ctx.state, {
  sceneProgram, downProgram, upProgram, finalProgram,
  deflectionTex, inverseRadiusTex, blackBodyTex, noiseTex, luminanceAt,
  camera, lastDistance: null, spin: 0, drift: 0, t: 0, targets: null, size: null,
});

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const LEVELS = 6;

// Render the ray tracer at up to ~2.4 MP and bloom/tone map up to the canvas (keeps 4K and retina at 60 fps).
const scale = Math.min(1, Math.sqrt(2.4e6 / (w * h)));
const sw = Math.max(2, Math.round(w * scale)), sh = Math.max(2, Math.round(h * scale));
if (!s.targets || s.size[0] !== sw || s.size[1] !== sh) {
  const make = (tw, th) => {
    const texture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, tw, th, 0, gl.RGBA, gl.HALF_FLOAT, null);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    const framebuffer = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
    return { texture, framebuffer, w: tw, h: th };
  };
  if (s.targets) for (const t of [s.targets.hdr, ...s.targets.down, ...s.targets.up]) { gl.deleteTexture(t.texture); gl.deleteFramebuffer(t.framebuffer); }
  const down = [], up = [];
  for (let i = 1; i <= LEVELS; i++) down.push(make(Math.max(1, sw >> i), Math.max(1, sh >> i)));
  for (let i = 1; i < LEVELS; i++) up.push(make(Math.max(1, sw >> i), Math.max(1, sh >> i)));
  s.targets = { hdr: make(sw, sh), down, up };
  s.size = [sw, sh];
}

// Camera: the shared orbit camera (drag orbits, scroll zooms, double-click resets) plus a slow automatic orbit.
const cam = s.camera;
if (u.u_distance !== s.lastDistance) { cam.setDistance(u.u_distance); s.lastDistance = u.u_distance; }
cam.setTarget(0, 0, 0);
cam.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const dt = Math.min(ctx.dt, 0.1);
if (!ctx.mouseDown) s.spin += u.u_orbit * dt;
// While untouched, the view also rises and sinks a little over the disc (about ±7°, a 50 s cycle).
if (!ctx.mouseDown) s.drift += dt * u.u_orbit / 0.07;
const E = cam.getEye(), rr = Math.hypot(E[0], E[1], E[2]);
const el = Math.max(-1.5, Math.min(1.5, Math.asin(E[1] / rr) + 0.12 * Math.sin(s.drift * 0.125)));
const az = Math.atan2(E[0], E[2]) + s.spin;
const ex = rr * Math.cos(el) * Math.sin(az), ey = rr * Math.sin(el), ez = rr * Math.cos(el) * Math.cos(az);
// Orbit-camera space is y-up; the black hole's frame has the disc in the z = 0 plane.
const P = [ez, ex, ey];
const r = Math.hypot(P[0], P[1], P[2]);
const theta = Math.acos(Math.max(-1, Math.min(1, P[2] / r))), phi = Math.atan2(P[1], P[0]);

// A static observer at (r, theta, phi) looking at the black hole (model.js with yaw = pitch = 0, state STOPPED):
// e_tau = e_t (no spatial part), e_w = e_phi, e_h = -e_theta, e_d = sqrt(1 - 1/r) e_r, k_s = (1/sqrt(1 - 1/r), 0, 0, 0).
const ct = Math.cos(theta), st = Math.sin(theta), cp = Math.cos(phi), sp = Math.sin(phi), v = Math.sqrt(1 - 1 / r);
const ur = [st * cp, st * sp, ct], eTheta = [ct * cp, ct * sp, -st], ePhi = [-sp, cp, 0];

// Disc time in units of r_s / c (the demo advances it by c^3 / 2GM per second; here a gentle, adjustable pace).
s.t += dt * 28 * u.u_speed / v;

// Stars: a fixed tilt so the Milky Way band crosses the disc at an angle.
const a = 1.05, b = 0.5, ca = Math.cos(a), sa = Math.sin(a), cb = Math.cos(b), sb = Math.sin(b);
const starsMatrix = [cb, sa * sb, -ca * sb, 0, ca, sa, sb, -sa * cb, ca * cb];

// 50° across the shorter side (the demo's vertical field of view), a bit wider in portrait.
const fovY = ((sw < sh ? 58 : 50) * Math.PI) / 180;
const focal = Math.min(sw, sh) / (2 * Math.tan(fovY / 2));

gl.bindFramebuffer(gl.FRAMEBUFFER, s.targets.hdr.framebuffer);
gl.viewport(0, 0, sw, sh);
gl.useProgram(s.sceneProgram);
ctx.utils.bindTexture(s.sceneProgram, "ray_deflection_texture", s.deflectionTex, 0);
ctx.utils.bindTexture(s.sceneProgram, "ray_inverse_radius_texture", s.inverseRadiusTex, 1);
ctx.utils.bindTexture(s.sceneProgram, "black_body_texture", s.blackBodyTex, 2);
ctx.utils.bindTexture(s.sceneProgram, "noise_texture", s.noiseTex, 3);
ctx.utils.drawFullscreen(s.sceneProgram, {
  camera_position: [s.t, r, theta, phi],
  p: [r * ur[0], r * ur[1], r * ur[2]],
  k_s: [1 / v, 0, 0, 0],
  e_tau: [0, 0, 0], e_w: ePhi, e_h: [-eTheta[0], -eTheta[1], -eTheta[2]], e_d: [v * ur[0], v * ur[1], v * ur[2]],
  disc_params: [1, u.u_opacity, u.u_temperature],
  u_discScale: (0.6 * u.u_brightness) / s.luminanceAt(u.u_temperature),
  u_lensing: u.u_lensing ? 1 : 0, u_doppler: u.u_doppler ? 1 : 0, u_stars: 1,
  stars_orientation: starsMatrix,
  u_camera: [sw / 2, sh / 2, focal],
});

// Bloom pyramid.
let src = s.targets.hdr;
for (const dst of s.targets.down) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, dst.framebuffer);
  gl.viewport(0, 0, dst.w, dst.h);
  gl.useProgram(s.downProgram);
  ctx.utils.bindTexture(s.downProgram, "u_src", src.texture, 0);
  ctx.utils.drawFullscreen(s.downProgram, { u_texel: [1 / src.w, 1 / src.h] });
  src = dst;
}
for (let i = LEVELS - 2; i >= 0; i--) {
  const dst = s.targets.up[i];
  gl.bindFramebuffer(gl.FRAMEBUFFER, dst.framebuffer);
  gl.viewport(0, 0, dst.w, dst.h);
  gl.useProgram(s.upProgram);
  ctx.utils.bindTexture(s.upProgram, "u_src", src.texture, 0);
  ctx.utils.bindTexture(s.upProgram, "u_add", s.targets.down[i].texture, 1);
  ctx.utils.drawFullscreen(s.upProgram, { u_texel: [1 / src.w, 1 / src.h] });
  src = dst;
}

gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
gl.useProgram(s.finalProgram);
ctx.utils.bindTexture(s.finalProgram, "u_src", s.targets.hdr.texture, 0);
ctx.utils.bindTexture(s.finalProgram, "u_bloom", src.texture, 1);
ctx.utils.drawFullscreen(s.finalProgram, { u_texel: [1 / sw, 1 / sh], u_bloomMix: u.u_bloom * 0.35, u_exp: u.u_exposure, u_levels: LEVELS });

ctx.publish("camera r (Schwarzschild radii)", Math.round(r * 10) / 10);
ctx.publish("render scale", Math.round(scale * 100) / 100);
